181: /* ---------- input ---------- */
182: function onKeyDown(e) {
183:   if (e.code === 'KeyF') {
184:     flashlightOn = !flashlightOn;
185:     flashlight.intensity = flashlightOn ? 3.2 : 0;
186:     flashStateEl.textContent = flashlightOn ? 'ON' : 'OFF';
187:     return;
188:   }
189:   if (e.code === 'Escape') { controls.unlock(); return; }
190:   if (e.code === 'KeyE') { doInteract(); return; }
191:   if (!isLocked && e.code !== 'KeyW' && e.code !== 'KeyS' && e.code !== 'KeyA' && e.code !== 'KeyD') return;
192: 
193:   switch (e.code) {
194:     case 'KeyW': move.forward = 1; break;
195:     case 'KeyS': move.backward = 1; break;
196:     case 'KeyA': move.left = 1; break;
197:     case 'KeyD': move.right = 1; break;
198:     case 'ShiftLeft': isSprinting = true; break;
199:   }
200: }
201: function onKeyUp(e) {
202:   switch (e.code) {
203:     case 'KeyW': move.forward = 0; break;
204:     case 'KeyS': move.backward = 0; break;
205:     case 'KeyA': move.left = 0; break;
206:     case 'KeyD': move.right = 0; break;
207:     case 'ShiftLeft': isSprinting = false; break;
208:   }
209: }
210: function onResize() {
211:   camera.aspect = window.innerWidth / window.innerHeight;
212:   camera.updateProjectionMatrix();
213:   renderer.setSize(window.innerWidth, window.innerHeight);
214: }
215: 
216: /* ---------- interaction ---------- */
217: function doInteract() {
218:   const dir = new THREE.Vector3();
219:   camera.getWorldDirection(dir);
220:   const pos = camera.position.clone();
221:   let best = null, bestD = 1e9;
222:   for (const it of interactables) {
223:     const v = it.mesh.position.clone().sub(pos);
224:     const fwd = v.dot(dir);
225:     if (fwd < 0.6 || fwd > it.dist) continue;
226:     const vh = v.clone(); vh.y = 0; vh.normalize();
227:     const dh = dir.clone(); dh.y = 0; dh.normalize();
228:     const ang = Math.acos(Math.max(-1, Math.min(1, vh.dot(dh))));
229:     if (ang > 0.95) continue;
230:     if (fwd < bestD) { bestD = fwd; best = it; }
231:   }
232:   if (best) showMessage(best.text + ' — ' + (best.mesh.userData.open ? '열림' : '잠김'));
233:   else showMessage('상호작용할 대상이 없습니다.');
234: }
235: 
236: function showMessage(t) {
237:   msgEl.textContent = t;
238:   msgEl.classList.remove('hidden');
239:   msgTimer = 110;
240: }
241: 
242: /* ---------- suspicion / disguise mechanic ---------- */
243: function updateSuspicion() {
244:   const moving = move.forward || move.backward || move.left || move.right;
245:   if (isLocked && moving) {
246:     suspicion += isSprinting ? 1.1 : 0.25;
247:   } else {
248:     suspicion = Math.max(0, suspicion - 0.12);
249:   }
250:   suspicion = Math.min(100, suspicion);
251:   suspicionFill.style.width = suspicion + '%';
252:   suspicionFill.style.backgroundColor =
253:     suspicion > 70 ? '#ef4444' : suspicion > 40 ? '#f59e0b' : '#22c55e';
254:   if (suspicion >= 100 && Math.random() < 0.02) showMessage('복도를 순회하는 인영이 당신을 주시합니다.');
255: }
256: 
257: /* ---------- ambience ---------- */
258: function flickerLights(lights) {
259:   for (const pl of lights) {
260:     if (Math.random() < 0.25) pl.intensity = 0.5 + Math.random() * 0.6;
261:   }
262: }
