264: /* ---------- main loop ---------- */
265: function animate() {
266:   requestAnimationFrame(animate);
267:   const now = performance.now();
268:   const dt = Math.min(0.05, (now - prevTime) / 1000);
269:   prevTime = now;
270: 
271:   if (controls.isLocked) {
272:     const speed = isSprinting ? SPRINT : SPEED;
273:     const dir = new THREE.Vector3(move.left - move.right, 0, move.forward - move.backward);
274:     if (dir.lengthSq() > 0) {
275:       dir.normalize();
276:       // move relative to camera facing
277:       const forward = new THREE.Vector3();
278:       camera.getWorldDirection(forward);
279:       forward.y = 0; forward.normalize();
280:       const right = new THREE.Vector3().crossVectors(forward, new THREE.Vector3(0, 1, 0));
281:       const offset = forward.clone().multiplyScalar(-dir.z).add(right.clone().multiplyScalar(dir.x));
282:       camera.position.add(offset.multiplyScalar(speed * dt));
283:     }
284:     camera.position.y = PLAYER_HEIGHT;
285:     // keep inside school bounds
286:     camera.position.x = Math.max(-20, Math.min(20, camera.position.x));
287:     camera.position.z = Math.max(-26, Math.min(3, camera.position.z));
288: 
289:     // 학생 NPC 업데이트 (시선 반응 이동)
290:     npcManager.update(camera, dt);
291:   }
292: 
293:   if (msgTimer > 0) { msgTimer--; if (msgTimer === 0) msgEl.classList.add('hidden'); }
294: 
295:   updateSuspicion();
296:   renderer.render(scene, camera);
297: }
